def has_digit_1(x):
    return '1' in str(x)

def is_solitary(n):
    """n is solitary iff for every a+b=n, at least one of a,b has digit 1.
    Equivalently, n is NOT solitary iff there exist a,b with a+b=n, both 1-free."""
    for a in range(n+1):
        b = n - a
        if not has_digit_1(a) and not has_digit_1(b):
            return False
    return True

# Find all solitary numbers less than 10^4
solitary = []
for n in range(1, 10000):
    if is_solitary(n):
        solitary.append(n)

print(f"Count less than 10^4: {len(solitary)}")
print(f"2^4 - 1 = {2**4 - 1}")
print(f"Solitary numbers less than 1000: {[x for x in solitary if x < 1000]}")
print(f"Solitary numbers 1000-9999: {[x for x in solitary if x >= 1000]}")

# Check counts for each power of 10
for k in range(1, 5):
    cnt = sum(1 for x in solitary if x < 10**k)
    print(f"Count less than 10^{k}: {cnt}, 2^{k}-1 = {2**k - 1}")
